package com.fasterxml.jackson.databind.ser.impl;

import com.fasterxml.jackson.annotation.ObjectIdGenerator;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.SerializableString;
import com.fasterxml.jackson.core.io.ByteSequenceInput;
import com.fasterxml.jackson.core.io.JsonFactory;
import com.fasterxml.jackson.core.io.JsonParser;
import com.fasterxml.jackson.core.io.JsonToken;
import com.fasterxml.jackson.core.io.SerializedString;
import com.fasterxml.jackson.core.io.tnt;
import com.fasterxml.jackson.databind.SerializerProvider;
import com.fasterxml.jackson.databind.ser.ObjectIdWriter;
import com.fasterxml.jackson.databind.ser.std.StringSerializer;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Field;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.*;

public class WritableObjectId_writeAsField_TriageGen0Test {

    private JsonGenerator gen;
    private SerializerProvider provider;
    private ObjectIdWriter w;
    private ObjectIdGenerator<?> generator;
    private WritableObjectId writableObjectId;

    @Before
    public void setUp() throws Exception {
        gen = mock(JsonGenerator.class);
        provider = mock(SerializerProvider.class);
        w = mock(ObjectIdWriter.class);
        generator = mock(ObjectIdGenerator.class);
        writableObjectId = new WritableObjectId(generator);

        // Use reflection to set the private 'id' field for testing purposes
        Field idField = WritableObjectId.class.getDeclaredField("id");
        idField.setAccessible(true);
        idField.set(writableObjectId, 123L);
    }

    @Test
    public void testWriteAsField_WithCanWriteObjectIdTrue() throws IOException {
        // Arrange
        when(gen.canWriteObjectId()).thenReturn(true);

        // Act
        writableObjectId.writeAsField(gen, provider, w);

        // Assert
        verify(gen).writeObjectId("123");
        verify(gen, never()).writeFieldName(any(SerializableString.class));
        verify(w, never()).serializer; // No interaction with property name/serializer if canWriteObjectId is true
        assertTrue(writableObjectId.isIdWritten());
    }

    @Test
    public void testWriteAsField_WithCanWriteObjectIdFalse_AndNameNotNull() throws IOException {
        // Arrange
        when(gen.canWriteObjectId()).thenReturn(false);
        SerializableString name = SerializedString.newString("id_field");
        w.propertyName = name;

        // Mock serializer to avoid NullPointerException during serialize call
        w.serializer = mock(com.fasterxml.jackson.databind.JsonSerializer.class);

        // Act
        writableObjectId.writeAsField(gen, provider, w);

        // Assert
        verify(gen).writeFieldName(name);
        verify(w.serializer).serialize(eq(123L), eq(gen), eq(provider));
        assertTrue(writableObjectId.isIdWritten());
    }

    @Test
    public void testWriteAsField_WithCanWriteObjectIdFalse_AndNameIsNull() throws IOException {
        // Arrange
        when(gen.canWriteObjectId()).thenReturn(false);
        w.propertyName = null;

        // Act
        writableObjectId.writeAsField(gen, provider, w);

        // Assert
        verify(gen, never()).writeFieldName(any(SerializableString.class));
        verify(gen, never()).writeObjectId(anyString());
        assertTrue(writableObjectId.isIdWritten());
    }
}
